package ai.eva.android.probe;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;
/** Isolated fixture-only tests; no kernel processes or network requests. */
public final class ProviderHistoryProjectionTest {
 static int checks;static void require(boolean value,String name){checks++;if(!value)throw new AssertionError(name);}interface Checked{void run()throws Exception;}
 static void rejects(Checked operation,String name)throws Exception{boolean failed=false;try{operation.run();}catch(Exception expected){failed=true;}require(failed,name);}
 static String withoutId(JSONObject item)throws Exception{JSONObject copy=new JSONObject(item.toString());copy.remove("id");return copy.toString();}
 static JSONObject item(String type,String id)throws Exception{return new JSONObject().put("type",type).put("id",id);}
 static JSONObject record(String type,JSONObject payload)throws Exception{return new JSONObject().put("type",type).put("payload",payload);}
 static byte[] rollout(String id,String provider,JSONObject base,JSONObject... records)throws Exception{StringBuilder out=new StringBuilder();JSONObject meta=new JSONObject().put("id",id).put("model_provider",provider);if(base!=null)meta.put("history_base",base);List<JSONObject> all=new ArrayList<>();all.add(record("session_meta",meta));all.addAll(Arrays.asList(records));for(int n=0;n<all.size();n++)out.append(new JSONObject(all.get(n).toString()).put("ordinal",n).toString()).append('\n');return out.toString().getBytes(StandardCharsets.UTF_8);}
 static File write(File home,String id,byte[] bytes)throws Exception{File folder=new File(home,"sessions/2026/11/05");folder.mkdirs();File file=new File(folder,"rollout-"+id+".jsonl");Files.write(file.toPath(),bytes);return file;}
 static JSONObject run(File home,File output,String id,String target,boolean explicit)throws Exception{return ProviderHistoryProjection.project(home,output,"/root/eva-workspace/.eva-provider-history",id,target,explicit);}
 static List<JSONObject> output(File directory,JSONObject result)throws Exception{String path=result.getString("path"),name=path.substring(path.lastIndexOf('/')+1);List<JSONObject> out=new ArrayList<>();for(String line:Files.readAllLines(new File(directory,name).toPath(),StandardCharsets.UTF_8))out.add(new JSONObject(line));return out;}
 public static int run(File root)throws Exception{
  checks=0;File home=new File(root,"home"),out=new File(root,"output");String id=UUID.randomUUID().toString();JSONObject reasoning=item("reasoning","r").put("content",new JSONArray().put(new JSONObject().put("type","reasoning_text").put("text","private fixture"))).put("encrypted_content","opaque fixture");JSONObject user=item("message","msg_u").put("role","user").put("content",new JSONArray().put(new JSONObject().put("type","input_text").put("text","preserve user")));JSONObject assistant=item("message","msg_a").put("role","assistant").put("content",new JSONArray().put(new JSONObject().put("type","output_text").put("text","preserve assistant")));JSONObject tool=item("function_call_output","tool").put("call_id","call").put("output","preserve tool");
  tool.remove("id");
  byte[] original=rollout(id,"foreign",null,record("response_item",user),record("response_item",reasoning),record("response_item",assistant),record("response_item",tool));File source=write(home,id,original);
  JSONObject missing=run(home,out,UUID.randomUUID().toString(),"openai",false);require(!missing.getBoolean("needed")&&missing.getString("reason").equals("unmaterialized"),"new empty thread without materialized rollout passes through");
  JSONObject same=run(home,out,id,"foreign",false);require(!same.getBoolean("needed")&&same.getString("reason").equals("same-provider-lineage"),"same provider skips full history scan");require(Arrays.equals(original,Files.readAllBytes(source.toPath())),"same-provider source unchanged");
  JSONObject projected=run(home,out,id,"openai",true);require(projected.getBoolean("needed")&&projected.getInt("removedReasoningItems")==1,"cross-provider private context projected");List<JSONObject> rows=output(out,projected);require(rows.size()==4,"only one reasoning response removed");JSONObject meta=rows.get(0).getJSONObject("payload");require(!meta.has("history_base")&&!meta.getString("id").equals(id)&&meta.getString("model_provider").equals("openai"),"independent target metadata");require(withoutId(rows.get(1).getJSONObject("payload")).equals(withoutId(user))&&withoutId(rows.get(2).getJSONObject("payload")).equals(withoutId(assistant))&&withoutId(rows.get(3).getJSONObject("payload")).equals(withoutId(tool)),"all nonreasoning payloads unchanged");require(Arrays.equals(original,Files.readAllBytes(source.toPath())),"source bytes unchanged");require(!projected.getJSONObject("audit").toString().contains("private fixture")&&!projected.getJSONObject("audit").toString().contains("opaque fixture"),"audit contains no reasoning or encrypted body");
  String child=UUID.randomUUID().toString();JSONObject base=new JSONObject().put("thread_id",id).put("end_byte_offset",original.length).put("end_ordinal_exclusive",5);write(home,child,rollout(child,"openai",base,record("response_item",item("configuration_update","config"))));JSONObject polluted=run(home,out,child,"openai",false);require(polluted.getBoolean("needed"),"same-provider child detects foreign ancestor");require(output(out,polluted).size()==5,"parent prefix flattened before suffix");
  byte[] prefix=rollout(id,"foreign",null,record("response_item",user));byte[] tail=rollout(id,"foreign",null,record("response_item",reasoning));byte[] full=Arrays.copyOf(prefix,prefix.length+tail.length);System.arraycopy(tail,0,full,prefix.length,tail.length);write(home,id,full);base.put("end_byte_offset",prefix.length).put("end_ordinal_exclusive",2);write(home,child,rollout(child,"openai",base));require(run(home,out,child,"openai",false).getBoolean("needed"),"parent prefix IDs normalized without reading excluded reasoning tail");
  write(home,id,original);base.put("end_byte_offset",original.length).put("end_ordinal_exclusive",5);JSONObject checkpoint=new JSONObject().put("replacement_history",new JSONArray().put(user).put(assistant));write(home,child,rollout(child,"openai",base,record("compacted",checkpoint)));require(run(home,out,child,"openai",false).getBoolean("needed"),"compaction without foreign reasoning still normalizes upstream IDs");checkpoint.put("replacement_history",new JSONArray().put(user).put(reasoning).put(assistant));write(home,child,rollout(child,"openai",base,record("compacted",checkpoint)));JSONObject compacted=run(home,out,child,"openai",false);require(compacted.getBoolean("needed")&&compacted.getInt("removedCheckpointReasoningItems")==1,"checkpoint retaining foreign reasoning projected");List<JSONObject> compactRows=output(out,compacted);require(compactRows.get(compactRows.size()-1).getJSONObject("payload").getJSONArray("replacement_history").length()==2,"checkpoint nonreasoning entries preserved");
  base.put("end_byte_offset",original.length-1);write(home,child,rollout(child,"openai",base));rejects(()->run(home,out,child,"openai",false),"partial parent byte boundary rejected");base.put("end_byte_offset",original.length).put("end_ordinal_exclusive",4);write(home,child,rollout(child,"openai",base));rejects(()->run(home,out,child,"openai",false),"incorrect ordinal boundary rejected");
  base.put("thread_id",UUID.randomUUID().toString()).put("end_byte_offset",original.length).put("end_ordinal_exclusive",5);write(home,child,rollout(child,"openai",base));rejects(()->run(home,out,child,"openai",false),"known child missing parent fails closed");
  String large=UUID.randomUUID().toString();char[] image=new char[9*1024*1024];Arrays.fill(image,'x');JSONObject imageUser=item("message","image-user").put("role","user").put("content",new JSONArray().put(new JSONObject().put("type","input_image").put("image_url","data:image/png;base64,"+new String(image))));write(home,large,rollout(large,"foreign",null,record("response_item",imageUser),record("response_item",reasoning)));JSONObject largeResult=run(home,out,large,"openai",true);require(largeResult.getBoolean("needed")&&output(out,largeResult).get(1).getJSONObject("payload").getJSONArray("content").getJSONObject(0).getString("image_url").length()>9*1024*1024,"9MiB image record survives projection unchanged");
  rejects(()->run(home,out,"../../auth.json","openai",true),"path traversal rejected");String loop=UUID.randomUUID().toString();JSONObject cycle=new JSONObject().put("thread_id",loop).put("end_byte_offset",1).put("end_ordinal_exclusive",1);write(home,loop,rollout(loop,"foreign",cycle));rejects(()->run(home,out,loop,"openai",true),"cycle rejected");
  require(Arrays.equals(original,Files.readAllBytes(source.toPath())),"all original parent bytes still unchanged");return checks;
 }
 public static void main(String[] args)throws Exception{File root=Files.createTempDirectory("eva-provider-projection-").toFile();try{System.out.println("PASS ProviderHistoryProjection "+run(root)+" checks");}finally{try(java.util.stream.Stream<Path> paths=Files.walk(root.toPath())){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(IOException e){throw new UncheckedIOException(e);}});}}}
}
